        self.val = val
        self.left = left
        self.right = right
        self.random = random

def cloneTree(root):
    if not root:
        return None

    # Create a new node with the same value as the root
    new_root = Node(root.val)

    # Use a dictionary to map original nodes to their clones
    old_to_new = {root: new_root}

